using System;using System.Linq;using UnityEngine;using AntColony.Buildings;
public static class Final1113BedSurface {public static string Run(){var b=GameObject.Find("Final bed probe");var m=b.GetComponent<FacilityVisual>().Model;var list=new System.Collections.Generic.List<MeshCollider>();foreach(var f in m.GetComponentsInChildren<MeshFilter>()){var col=f.gameObject.AddComponent<MeshCollider>();col.sharedMesh=f.sharedMesh;list.Add(col);}Physics.SyncTransforms();string result="";foreach(float x in new[]{-1f,-.5f,0,.5f,1f})foreach(float z in new[]{-.4f,0,.4f}){var p=b.transform.position+new Vector3(x,5,z);float y=float.NegativeInfinity;foreach(var col in list)if(col.Raycast(new Ray(p,Vector3.down),out var hit,10))y=Mathf.Max(y,hit.point.y);result+=$"x{x} z{z} height from floor{y-(b.transform.position.y-1):F4}\n";}foreach(var col in list)UnityEngine.Object.Destroy(col);return result;}}
